    CalculateRouteCarModeOptions.add_member(:avoid_tolls, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'AvoidTolls', traits: {"smithy.api#documentation" => "<p>Avoids tolls when calculating routes.</p>\n         <p>Default Value: <code>false</code>\n         </p>\n         <p>Valid Values: <code>false</code> | <code>true</code>\n         </p>"}))
    CalculateRouteCarModeOptions.type = Types::CalculateRouteCarModeOptions
    CalculateRouteInput.add_member(:calculator_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'CalculatorName', traits: {"smithy.api#documentation" => "<p>The name of the route calculator resource that you want to use to calculate the route.\n        </p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CalculateRouteInput.add_member(:departure_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Position, location_name: 'DeparturePosition', traits: {"smithy.api#documentation" => "<p>The start position for the route. Defined in <a href=\"https://earth-info.nga.mil/index.php?dir=wgs84&amp;action=wgs84\">World Geodetic\n            System (WGS 84)</a> format:\n                <code>[longitude, latitude]</code>.</p>\n         <ul>\n            <li>\n               <p>For example, <code>[-123.115, 49.285]</code>\n               </p>\n            </li>\n         </ul>\n         <note>\n            <p>If you specify a departure that's not located on a road, Amazon Location <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/snap-to-nearby-road.html\">moves the position\n                    to the nearest road</a>. If Esri is the provider for your route calculator,\n                specifying a route that is longer than 400 km returns a <code>400\n                    RoutesValidationException</code> error.</p>\n         </note>\n         <p>Valid Values: <code>[-180 to 180,-90 to 90]</code>\n         </p>", "smithy.api#required" => {}}))
    CalculateRouteInput.add_member(:destination_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Position, location_name: 'DestinationPosition', traits: {"smithy.api#documentation" => "<p>The finish position for the route. Defined in <a href=\"https://earth-info.nga.mil/index.php?dir=wgs84&amp;action=wgs84\">World Geodetic\n            System (WGS 84)</a> format:\n                <code>[longitude, latitude]</code>.</p>\n         <ul>\n            <li>\n               <p> For example, <code>[-122.339, 47.615]</code>\n               </p>\n            </li>\n         </ul>\n         <note>\n            <p>If you specify a destination that's not located on a road, Amazon Location <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/snap-to-nearby-road.html\">moves the position\n                    to the nearest road</a>. </p>\n         </note>\n         <p>Valid Values: <code>[-180 to 180,-90 to 90]</code>\n         </p>", "smithy.api#required" => {}}))
    CalculateRouteInput.add_member(:waypoint_positions, Smithy::Schema::Shapes::ShapeRef.new(shape: WaypointPositionList, location_name: 'WaypointPositions', traits: {"smithy.api#documentation" => "<p>Specifies an ordered list of up to 23 intermediate positions to include along a route\n            between the departure position and destination position. </p>\n         <ul>\n            <li>\n               <p>For example, from the <code>DeparturePosition</code>\n                  <code>[-123.115, 49.285]</code>, the route follows the order that the waypoint\n                    positions are given <code>[[-122.757, 49.0021],[-122.349, 47.620]]</code>\n               </p>\n            </li>\n         </ul>\n         <note>\n            <p>If you specify a waypoint position that's not located on a road, Amazon Location <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/snap-to-nearby-road.html\">moves the position\n                    to the nearest road</a>. </p>\n            <p>Specifying more than 23 waypoints returns a <code>400 ValidationException</code>\n                error.</p>\n            <p>If Esri is the provider for your route calculator, specifying a route that is\n                longer than 400 km returns a <code>400 RoutesValidationException</code>\n                error.</p>\n         </note>\n         <p>Valid Values: <code>[-180 to 180,-90 to 90]</code>\n         </p>", "smithy.api#length" => {"max" => 23}}))
    CalculateRouteInput.add_member(:travel_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TravelMode, location_name: 'TravelMode', traits: {"smithy.api#documentation" => "<p>Specifies the mode of transport when calculating a route. Used in estimating the speed\n            of travel and road compatibility. You can choose <code>Car</code>, <code>Truck</code>, \n            <code>Walking</code>, <code>Bicycle</code> or <code>Motorcycle</code> as options for \n            the <code>TravelMode</code>.</p>\n         <note>\n            <p>\n               <code>Bicycle</code> and <code>Motorcycle</code> are only valid when using Grab as\n                a data provider, and only within Southeast Asia.</p>\n            <p>\n               <code>Truck</code> is not available for Grab.</p>\n            <p>For more details on the using Grab for routing, including areas of coverage, see\n                    <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/grab.html\">GrabMaps</a> in the <i>Amazon Location Service Developer Guide</i>.</p>\n         </note>\n         <p>The <code>TravelMode</code> you specify also determines how you specify route\n            preferences: </p>\n         <ul>\n            <li>\n               <p>If traveling by <code>Car</code> use the <code>CarModeOptions</code>\n                    parameter.</p>\n            </li>\n            <li>\n               <p>If traveling by <code>Truck</code> use the <code>TruckModeOptions</code>\n                    parameter.</p>\n            </li>\n         </ul>\n         <p>Default Value: <code>Car</code>\n         </p>"}))
    CalculateRouteInput.add_member(:departure_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'DepartureTime', traits: {"smithy.api#documentation" => "<p>Specifies the desired time of departure. Uses the given time to calculate the route.\n            Otherwise, the best time of day to travel with the best traffic conditions is used to\n            calculate the route.</p>\n         <ul>\n            <li>\n               <p>In <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO\n                        8601</a> format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>. For example,\n                        <code>2020–07-2T12:15:20.000Z+01:00</code>\n               </p>\n            </li>\n         </ul>"}))
    CalculateRouteInput.add_member(:depart_now, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'DepartNow', traits: {"smithy.api#documentation" => "<p>Sets the time of departure as the current time. Uses the current time to calculate a\n            route. Otherwise, the best time of day to travel with the best traffic conditions is\n            used to calculate the route.</p>\n         <p>Default Value: <code>false</code>\n         </p>\n         <p>Valid Values: <code>false</code> | <code>true</code>\n         </p>"}))
    CalculateRouteInput.add_member(:distance_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: DistanceUnit, location_name: 'DistanceUnit', traits: {"smithy.api#documentation" => "<p>Set the unit system to specify the distance.</p>\n         <p>Default Value: <code>Kilometers</code>\n         </p>"}))
    CalculateRouteInput.add_member(:include_leg_geometry, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'IncludeLegGeometry', traits: {"smithy.api#documentation" => "<p>Set to include the geometry details in the result for each path between a pair of\n            positions.</p>\n         <p>Default Value: <code>false</code>\n         </p>\n         <p>Valid Values: <code>false</code> | <code>true</code>\n         </p>"}))
    CalculateRouteInput.add_member(:car_mode_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculateRouteCarModeOptions, location_name: 'CarModeOptions', traits: {"smithy.api#documentation" => "<p>Specifies route preferences when traveling by <code>Car</code>, such as avoiding\n            routes that use ferries or tolls.</p>\n         <p>Requirements: <code>TravelMode</code> must be specified as <code>Car</code>.</p>"}))
    CalculateRouteInput.add_member(:truck_mode_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculateRouteTruckModeOptions, location_name: 'TruckModeOptions', traits: {"smithy.api#documentation" => "<p>Specifies route preferences when traveling by <code>Truck</code>, such as avoiding\n            routes that use ferries or tolls, and truck specifications to consider when choosing an\n            optimal road.</p>\n         <p>Requirements: <code>TravelMode</code> must be specified as <code>Truck</code>.</p>"}))
    CalculateRouteInput.add_member(:arrival_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'ArrivalTime', traits: {"smithy.api#documentation" => "<p>Specifies the desired time of arrival. Uses the given time to calculate the route. \n            Otherwise, the best time of day to travel with the best traffic conditions is used to calculate the route.</p>\n         <note>\n            <p>ArrivalTime is not supported Esri.</p>\n         </note>"}))
    CalculateRouteInput.add_member(:optimize_for, Smithy::Schema::Shapes::ShapeRef.new(shape: OptimizationMode, location_name: 'OptimizeFor', traits: {"smithy.api#documentation" => "<p>Specifies the distance to optimize for when calculating a route.</p>"}))
    CalculateRouteInput.add_member(:key, Smithy::Schema::Shapes::ShapeRef.new(shape: ApiKey, location_name: 'Key', traits: {"smithy.api#documentation" => "<p>The optional <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/using-apikeys.html\">API key</a> to authorize \n            the request.</p>", "smithy.api#httpQuery" => "key"}))
    CalculateRouteInput.type = Types::CalculateRouteInput
    CalculateRouteMatrixInput.add_member(:calculator_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'CalculatorName', traits: {"smithy.api#documentation" => "<p>The name of the route calculator resource that you want to use to calculate the route\n            matrix. </p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CalculateRouteMatrixInput.add_member(:departure_positions, Smithy::Schema::Shapes::ShapeRef.new(shape: PositionList, location_name: 'DeparturePositions', traits: {"smithy.api#documentation" => "<p>The list of departure (origin) positions for the route matrix. An array of points,\n            each of which is itself a 2-value array defined in <a href=\"https://earth-info.nga.mil/GandG/wgs84/index.html\">WGS 84</a> format:\n                <code>[longitude, latitude]</code>. For example, <code>[-123.115,\n            49.285]</code>.</p>\n         <important>\n            <p>Depending on the data provider selected in the route calculator resource there may\n                be additional restrictions on the inputs you can choose. See <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/calculate-route-matrix.html#matrix-routing-position-limits\"> Position restrictions</a> in the <i>Amazon Location Service Developer\n                    Guide</i>.</p>\n         </important>\n         <note>\n            <p>For route calculators that use Esri as the data provider, if you specify a\n                departure that's not located on a road, Amazon Location <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/snap-to-nearby-road.html\"> moves the\n                    position to the nearest road</a>. The snapped value is available in the\n                result in <code>SnappedDeparturePositions</code>.</p>\n         </note>\n         <p>Valid Values: <code>[-180 to 180,-90 to 90]</code>\n         </p>", "smithy.api#length" => {"min" => 1, "max" => 350}, "smithy.api#required" => {}}))
    CalculateRouteMatrixInput.add_member(:destination_positions, Smithy::Schema::Shapes::ShapeRef.new(shape: PositionList, location_name: 'DestinationPositions', traits: {"smithy.api#documentation" => "<p>The list of destination positions for the route matrix. An array of points, each of\n            which is itself a 2-value array defined in <a href=\"https://earth-info.nga.mil/GandG/wgs84/index.html\">WGS 84</a> format:\n                <code>[longitude, latitude]</code>. For example, <code>[-122.339,\n            47.615]</code>\n         </p>\n         <important>\n            <p>Depending on the data provider selected in the route calculator resource there may\n                be additional restrictions on the inputs you can choose. See <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/calculate-route-matrix.html#matrix-routing-position-limits\"> Position restrictions</a> in the <i>Amazon Location Service Developer\n                    Guide</i>.</p>\n         </important>\n         <note>\n            <p>For route calculators that use Esri as the data provider, if you specify a\n                destination that's not located on a road, Amazon Location <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/snap-to-nearby-road.html\"> moves the\n                    position to the nearest road</a>. The snapped value is available in the\n                result in <code>SnappedDestinationPositions</code>.</p>\n         </note>\n         <p>Valid Values: <code>[-180 to 180,-90 to 90]</code>\n         </p>", "smithy.api#length" => {"min" => 1, "max" => 350}, "smithy.api#required" => {}}))
    CalculateRouteMatrixInput.add_member(:travel_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TravelMode, location_name: 'TravelMode', traits: {"smithy.api#documentation" => "<p>Specifies the mode of transport when calculating a route. Used in estimating the speed\n            of travel and road compatibility.</p>\n         <p>The <code>TravelMode</code> you specify also determines how you specify route\n            preferences: </p>\n         <ul>\n            <li>\n               <p>If traveling by <code>Car</code> use the <code>CarModeOptions</code>\n                    parameter.</p>\n            </li>\n            <li>\n               <p>If traveling by <code>Truck</code> use the <code>TruckModeOptions</code>\n                    parameter.</p>\n            </li>\n         </ul>\n         <note>\n            <p>\n               <code>Bicycle</code> or <code>Motorcycle</code> are only valid when using\n                    <code>Grab</code> as a data provider, and only within Southeast Asia.</p>\n            <p>\n               <code>Truck</code> is not available for Grab.</p>\n            <p>For more information about using Grab as a data provider, see <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/grab.html\">GrabMaps</a> in the <i>Amazon Location Service Developer Guide</i>.</p>\n         </note>\n         <p>Default Value: <code>Car</code>\n         </p>"}))
    CalculateRouteMatrixInput.add_member(:departure_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'DepartureTime', traits: {"smithy.api#documentation" => "<p>Specifies the desired time of departure. Uses the given time to calculate the route\n            matrix. You can't set both <code>DepartureTime</code> and <code>DepartNow</code>. If\n            neither is set, the best time of day to travel with the best traffic conditions is used\n            to calculate the route matrix.</p>\n         <note>\n            <p>Setting a departure time in the past returns a <code>400\n                    ValidationException</code> error.</p>\n         </note>\n         <ul>\n            <li>\n               <p>In <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO\n                        8601</a> format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>. For example,\n                        <code>2020–07-2T12:15:20.000Z+01:00</code>\n               </p>\n            </li>\n         </ul>"}))
    CalculateRouteMatrixInput.add_member(:depart_now, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'DepartNow', traits: {"smithy.api#documentation" => "<p>Sets the time of departure as the current time. Uses the current time to calculate the\n            route matrix. You can't set both <code>DepartureTime</code> and <code>DepartNow</code>.\n            If neither is set, the best time of day to travel with the best traffic conditions is\n            used to calculate the route matrix.</p>\n         <p>Default Value: <code>false</code>\n         </p>\n         <p>Valid Values: <code>false</code> | <code>true</code>\n         </p>"}))
    CalculateRouteMatrixInput.add_member(:distance_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: DistanceUnit, location_name: 'DistanceUnit', traits: {"smithy.api#documentation" => "<p>Set the unit system to specify the distance.</p>\n         <p>Default Value: <code>Kilometers</code>\n         </p>"}))
    CalculateRouteMatrixInput.add_member(:car_mode_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculateRouteCarModeOptions, location_name: 'CarModeOptions', traits: {"smithy.api#documentation" => "<p>Specifies route preferences when traveling by <code>Car</code>, such as avoiding\n            routes that use ferries or tolls.</p>\n         <p>Requirements: <code>TravelMode</code> must be specified as <code>Car</code>.</p>"}))
    CalculateRouteMatrixInput.add_member(:truck_mode_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculateRouteTruckModeOptions, location_name: 'TruckModeOptions', traits: {"smithy.api#documentation" => "<p>Specifies route preferences when traveling by <code>Truck</code>, such as avoiding\n            routes that use ferries or tolls, and truck specifications to consider when choosing an\n            optimal road.</p>\n         <p>Requirements: <code>TravelMode</code> must be specified as <code>Truck</code>.</p>"}))
    CalculateRouteMatrixInput.add_member(:key, Smithy::Schema::Shapes::ShapeRef.new(shape: ApiKey, location_name: 'Key', traits: {"smithy.api#documentation" => "<p>The optional <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/using-apikeys.html\">API key</a> to authorize \n            the request.</p>", "smithy.api#httpQuery" => "key"}))
    CalculateRouteMatrixInput.type = Types::CalculateRouteMatrixInput
    CalculateRouteMatrixOutput.add_member(:route_matrix, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteMatrix, location_name: 'RouteMatrix', traits: {"smithy.api#documentation" => "<p>The calculated route matrix containing the results for all pairs of\n                <code>DeparturePositions</code> to <code>DestinationPositions</code>. Each row\n            corresponds to one entry in <code>DeparturePositions</code>. Each entry in the row\n            corresponds to the route from that entry in <code>DeparturePositions</code> to an entry\n            in <code>DestinationPositions</code>. </p>", "smithy.api#required" => {}}))
    CalculateRouteMatrixOutput.add_member(:snapped_departure_positions, Smithy::Schema::Shapes::ShapeRef.new(shape: PositionList, location_name: 'SnappedDeparturePositions', traits: {"smithy.api#documentation" => "<p>For routes calculated using an Esri route calculator resource, departure positions are\n            snapped to the closest road. For Esri route calculator resources, this returns the list\n            of departure/origin positions used for calculation of the\n            <code>RouteMatrix</code>.</p>", "smithy.api#length" => {"min" => 1, "max" => 350}}))
    CalculateRouteMatrixOutput.add_member(:snapped_destination_positions, Smithy::Schema::Shapes::ShapeRef.new(shape: PositionList, location_name: 'SnappedDestinationPositions', traits: {"smithy.api#documentation" => "<p>The list of destination positions for the route matrix used for calculation of the\n                <code>RouteMatrix</code>.</p>", "smithy.api#length" => {"min" => 1, "max" => 350}}))
    CalculateRouteMatrixOutput.add_member(:summary, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculateRouteMatrixSummary, location_name: 'Summary', traits: {"smithy.api#documentation" => "<p>Contains information about the route matrix, <code>DataSource</code>,\n                <code>DistanceUnit</code>, <code>RouteCount</code> and\n            <code>ErrorCount</code>.</p>", "smithy.api#required" => {}}))
    CalculateRouteMatrixOutput.type = Types::CalculateRouteMatrixOutput
    CalculateRouteMatrixSummary.add_member(:data_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'DataSource', traits: {"smithy.api#documentation" => "<p>The data provider of traffic and road network data used to calculate the routes.\n            Indicates one of the available providers:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Esri</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Grab</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Here</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information about data providers, see <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/what-is-data-provider.html\">Amazon Location Service data\n                providers</a>.</p>", "smithy.api#required" => {}}))
    CalculateRouteMatrixSummary.add_member(:route_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Integer, location_name: 'RouteCount', traits: {"smithy.api#documentation" => "<p>The count of cells in the route matrix. Equal to the number of\n                <code>DeparturePositions</code> multiplied by the number of\n                <code>DestinationPositions</code>.</p>", "smithy.api#range" => {"min" => 1, "max" => 160000}, "smithy.api#required" => {}}))
    CalculateRouteMatrixSummary.add_member(:error_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Integer, location_name: 'ErrorCount', traits: {"smithy.api#documentation" => "<p>The count of error results in the route matrix. If this number is 0, all routes were\n            calculated successfully.</p>", "smithy.api#range" => {"min" => 1, "max" => 160000}, "smithy.api#required" => {}}))
    CalculateRouteMatrixSummary.add_member(:distance_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: DistanceUnit, location_name: 'DistanceUnit', traits: {"smithy.api#documentation" => "<p>The unit of measurement for route distances.</p>", "smithy.api#required" => {}}))
    CalculateRouteMatrixSummary.type = Types::CalculateRouteMatrixSummary
    CalculateRouteOutput.add_member(:legs, Smithy::Schema::Shapes::ShapeRef.new(shape: LegList, location_name: 'Legs', traits: {"smithy.api#documentation" => "<p>Contains details about each path between a pair of positions included along a route\n            such as: <code>StartPosition</code>, <code>EndPosition</code>, <code>Distance</code>,\n                <code>DurationSeconds</code>, <code>Geometry</code>, and <code>Steps</code>. The\n            number of legs returned corresponds to one fewer than the total number of positions in\n            the request. </p>\n         <p>For example, a route with a departure position and destination position returns one\n            leg with the positions <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/snap-to-nearby-road.html\">snapped to a nearby\n                road</a>:</p>\n         <ul>\n            <li>\n               <p>The <code>StartPosition</code> is the departure position.</p>\n            </li>\n            <li>\n               <p>The <code>EndPosition</code> is the destination position.</p>\n            </li>\n         </ul>\n         <p>A route with a waypoint between the departure and destination position returns two\n            legs with the positions snapped to a nearby road:</p>\n         <ul>\n            <li>\n               <p>Leg 1: The <code>StartPosition</code> is the departure position . The\n                        <code>EndPosition</code> is the waypoint positon.</p>\n            </li>\n            <li>\n               <p>Leg 2: The <code>StartPosition</code> is the waypoint position. The\n                        <code>EndPosition</code> is the destination position.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CalculateRouteOutput.add_member(:summary, Smithy::Schema::Shapes::ShapeRef.new(shape: CalculateRouteSummary, location_name: 'Summary', traits: {"smithy.api#documentation" => "<p>Contains information about the whole route, such as: <code>RouteBBox</code>,\n                <code>DataSource</code>, <code>Distance</code>, <code>DistanceUnit</code>, and\n                <code>DurationSeconds</code>.</p>", "smithy.api#required" => {}}))
    CalculateRouteOutput.type = Types::CalculateRouteOutput
    CalculateRouteSummary.add_member(:route_b_box, Smithy::Schema::Shapes::ShapeRef.new(shape: BoundingBox, location_name: 'RouteBBox', traits: {"smithy.api#documentation" => "<p>Specifies a geographical box surrounding a route. Used to zoom into a route when\n            displaying it in a map. For example, <code>[min x, min y, max x, max y]</code>.</p>\n         <p>The first 2 <code>bbox</code> parameters describe the lower southwest corner: </p>\n         <ul>\n            <li>\n               <p>The first <code>bbox</code> position is the X coordinate or longitude of the\n                    lower southwest corner. </p>\n            </li>\n            <li>\n               <p>The second <code>bbox</code> position is the Y coordinate or latitude of the\n                    lower southwest corner. </p>\n            </li>\n         </ul>\n         <p>The next 2 <code>bbox</code> parameters describe the upper northeast corner: </p>\n         <ul>\n            <li>\n               <p>The third <code>bbox</code> position is the X coordinate, or longitude of the\n                    upper northeast corner. </p>\n            </li>\n            <li>\n               <p>The fourth <code>bbox</code> position is the Y coordinate, or latitude of the\n                    upper northeast corner. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CalculateRouteSummary.add_member(:data_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'DataSource', traits: {"smithy.api#documentation" => "<p>The data provider of traffic and road network data used to calculate the route.\n            Indicates one of the available providers:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Esri</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Grab</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Here</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information about data providers, see <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/what-is-data-provider.html\">Amazon Location Service data providers</a>.</p>", "smithy.api#required" => {}}))
    CalculateRouteSummary.add_member(:distance, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'Distance', traits: {"smithy.api#documentation" => "<p>The total distance covered by the route. The sum of the distance travelled between\n            every stop on the route.</p>\n         <note>\n            <p>If Esri is the data source for the route calculator, the route distance can’t be\n                greater than 400 km. If the route exceeds 400 km, the response is a <code>400\n                    RoutesValidationException</code> error.</p>\n         </note>", "smithy.api#range" => {"min" => 0}, "smithy.api#required" => {}}))
