    CreateRouteCalculatorOutput.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreateTime', traits: {"smithy.api#documentation" => "<p>The timestamp when the route calculator resource was created in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO 8601</a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>. </p>\n         <ul>\n            <li>\n               <p>For example, <code>2020–07-2T12:15:20.000Z+01:00</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
