    CreateTrackerInput.add_member(:tracker_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'TrackerName', traits: {"smithy.api#documentation" => "<p>The name for the tracker resource.</p>\n         <p>Requirements:</p>\n         <ul>\n            <li>\n               <p>Contain only alphanumeric characters (A-Z, a-z, 0-9) , hyphens (-), periods (.), and underscores (_).</p>\n            </li>\n            <li>\n               <p>Must be a unique tracker resource name.</p>\n            </li>\n            <li>\n               <p>No spaces allowed. For example, <code>ExampleTracker</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
