    ForecastGeofenceEventsRequest.add_member(:device_state, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastGeofenceEventsDeviceState, location_name: 'DeviceState', traits: {"smithy.api#documentation" => "<p>Represents the device's state, including its current position and speed. When speed is\n            omitted, this API performs a <i>containment check</i>. The\n                <i>containment check</i> operation returns <code>IDLE</code> events\n            for geofences where the device is currently inside of, but no other events.</p>", "smithy.api#required" => {}}))
    ForecastGeofenceEventsRequest.add_member(:time_horizon_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'TimeHorizonMinutes', traits: {"smithy.api#documentation" => "<p>The forward-looking time window for forecasting, specified in minutes. The API only\n            returns events that are predicted to occur within this time horizon. When no value is\n            specified, this API performs a <i>containment check</i>. The\n                <i>containment check</i> operation returns <code>IDLE</code> events\n            for geofences where the device is currently inside of, but no other events.</p>", "smithy.api#range" => {"min" => 0}}))
    ForecastGeofenceEventsRequest.add_member(:distance_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: DistanceUnit, location_name: 'DistanceUnit', traits: {"smithy.api#documentation" => "<p>The distance unit used for the <code>NearestDistance</code> property returned in a\n            forecasted event. The measurement system must match for <code>DistanceUnit</code> and\n                <code>SpeedUnit</code>; if <code>Kilometers</code> is specified for\n                <code>DistanceUnit</code>, then <code>SpeedUnit</code> must be\n                <code>KilometersPerHour</code>. </p>\n         <p>Default Value: <code>Kilometers</code>\n         </p>"}))
    ForecastGeofenceEventsRequest.add_member(:speed_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: SpeedUnit, location_name: 'SpeedUnit', traits: {"smithy.api#documentation" => "<p>The speed unit for the device captured by the device state. The measurement system\n            must match for <code>DistanceUnit</code> and <code>SpeedUnit</code>; if\n                <code>Kilometers</code> is specified for <code>DistanceUnit</code>, then\n                <code>SpeedUnit</code> must be <code>KilometersPerHour</code>.</p>\n         <p>Default Value: <code>KilometersPerHour</code>.</p>"}))
    ForecastGeofenceEventsRequest.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LargeToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>The pagination token specifying which page of results to return in the response. If no\n            token is provided, the default page is the first page.</p>\n         <p>Default value: <code>null</code>\n         </p>"}))
