    ForecastedEvent.add_member(:geofence_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Id, location_name: 'GeofenceId', traits: {"smithy.api#documentation" => "<p>The geofence identifier pertaining to the forecasted event.</p>", "smithy.api#required" => {}}))
    ForecastedEvent.add_member(:is_device_in_geofence, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'IsDeviceInGeofence', traits: {"smithy.api#documentation" => "<p>Indicates if the device is located within the geofence.</p>", "smithy.api#required" => {}}))
    ForecastedEvent.add_member(:nearest_distance, Smithy::Schema::Shapes::ShapeRef.new(shape: NearestDistance, location_name: 'NearestDistance', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The closest distance from the device's position to the geofence.</p>", "smithy.api#required" => {}}))
    ForecastedEvent.add_member(:event_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastedGeofenceEventType, location_name: 'EventType', traits: {"smithy.api#documentation" => "<p>The event type, forecasting three states for which a device can be in relative to a\n            geofence:</p>\n         <p>\n            <code>ENTER</code>: If a device is outside of a geofence, but would breach the fence\n            if the device is moving at its current speed within time horizon window.</p>\n         <p>\n            <code>EXIT</code>: If a device is inside of a geofence, but would breach the fence if\n            the device is moving at its current speed within time horizon window.</p>\n         <p>\n            <code>IDLE</code>: If a device is inside of a geofence, and the device is not\n            moving.</p>", "smithy.api#required" => {}}))
    ForecastedEvent.add_member(:forecasted_breach_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'ForecastedBreachTime', traits: {"smithy.api#documentation" => "<p>The forecasted time the device will breach the geofence in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO 8601</a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>\n         </p>"}))
