    GetDevicePositionHistoryInput.add_member(:start_time_inclusive, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartTimeInclusive', traits: {"smithy.api#documentation" => "<p>Specify the start time for the position history in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\"> ISO 8601</a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>. By default, the value will be 24 hours\n            prior to the time that the request is made.</p>\n         <p>Requirement:</p>\n         <ul>\n            <li>\n               <p>The time specified for <code>StartTimeInclusive</code> must be before\n                        <code>EndTimeExclusive</code>.</p>\n            </li>\n         </ul>"}))
    GetDevicePositionHistoryInput.add_member(:end_time_exclusive, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'EndTimeExclusive', traits: {"smithy.api#documentation" => "<p>Specify the end time for the position history in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\"> ISO 8601</a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>. By default, the value will be the time\n            that the request is made.</p>\n         <p>Requirement:</p>\n         <ul>\n            <li>\n               <p>The time specified for <code>EndTimeExclusive</code> must be after the time for\n                        <code>StartTimeInclusive</code>.</p>\n            </li>\n         </ul>"}))
    GetDevicePositionHistoryInput.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Integer, location_name: 'MaxResults', traits: {"smithy.api#default" => nil, "smithy.api#documentation" => "<p>An optional limit for the number of device positions returned in a single call.</p>\n         <p>Default value: <code>100</code>\n         </p>", "smithy.api#range" => {"min" => 1, "max" => 100}}))
