    GetDevicePositionOutput.add_member(:sample_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'SampleTime', traits: {"smithy.api#documentation" => "<p>The timestamp at which the device's position was determined. Uses <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\"> ISO 8601 </a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>. </p>", "smithy.api#required" => {}}))
