    GetGeofenceInput.add_member(:geofence_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Id, location_name: 'GeofenceId', traits: {"smithy.api#documentation" => "<p>The geofence you're retrieving details for.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    GetGeofenceInput.type = Types::GetGeofenceInput
    GetGeofenceOutput.add_member(:geofence_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Id, location_name: 'GeofenceId', traits: {"smithy.api#documentation" => "<p>The geofence identifier.</p>", "smithy.api#required" => {}}))
    GetGeofenceOutput.add_member(:geometry, Smithy::Schema::Shapes::ShapeRef.new(shape: GeofenceGeometry, location_name: 'Geometry', traits: {"smithy.api#documentation" => "<p>Contains the geofence geometry details describing the position of the geofence. Can be\n            a circle, a polygon, or a multipolygon.</p>", "smithy.api#required" => {}}))
    GetGeofenceOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>Identifies the state of the geofence. A geofence will hold one of the following\n            states:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ACTIVE</code> — The geofence has been indexed by the system. </p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING</code> — The geofence is being processed by the system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code> — The geofence failed to be indexed by the system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETED</code> — The geofence has been deleted from the system\n                    index.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> — The geofence is being deleted from the system\n                    index.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GetGeofenceOutput.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreateTime', traits: {"smithy.api#documentation" => "<p>The timestamp for when the geofence collection was created in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO 8601</a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>\n         </p>", "smithy.api#required" => {}}))
    GetGeofenceOutput.add_member(:update_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'UpdateTime', traits: {"smithy.api#documentation" => "<p>The timestamp for when the geofence collection was last updated in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO 8601</a>\n            format: <code>YYYY-MM-DDThh:mm:ss.sssZ</code>\n         </p>", "smithy.api#required" => {}}))
    GetGeofenceOutput.add_member(:geofence_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: PropertyMap, location_name: 'GeofenceProperties', traits: {"smithy.api#documentation" => "<p>User defined properties of the geofence. A property is a key-value pair stored with\n            the geofence and added to any geofence event triggered with that geofence.</p>\n         <p>Format: <code>\"key\" : \"value\"</code>\n         </p>"}))
