    Place.add_member(:neighborhood, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'Neighborhood', traits: {"smithy.api#documentation" => "<p>The name of a community district. For example, <code>Downtown</code>.</p>"}))
    Place.add_member(:municipality, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'Municipality', traits: {"smithy.api#documentation" => "<p>A name for a local area, such as a city or town name. For example,\n                <code>Toronto</code>.</p>"}))
    Place.add_member(:sub_region, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'SubRegion', traits: {"smithy.api#documentation" => "<p>A county, or an area that's part of a larger region. For example, <code>Metro\n                Vancouver</code>.</p>"}))
