    Place.add_member(:country, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'Country', traits: {"smithy.api#documentation" => "<p>A country/region specified using <a href=\"https://www.iso.org/iso-3166-country-codes.html\">ISO 3166</a> 3-digit\n            country/region code. For example, <code>CAN</code>.</p>"}))
    Place.add_member(:postal_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'PostalCode', traits: {"smithy.api#documentation" => "<p>A group of numbers and letters in a country-specific format, which accompanies the\n            address for the purpose of identifying a location. </p>"}))
    Place.add_member(:interpolated, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'Interpolated', traits: {"smithy.api#documentation" => "<p>\n            <code>True</code> if the result is interpolated from other known places.</p>\n         <p>\n            <code>False</code> if the Place is a known place.</p>\n         <p>Not returned when the partner does not provide the information.</p>\n         <p>For example, returns <code>False</code> for an address location that is found in the\n            partner data, but returns <code>True</code> if an address does not exist in the partner\n            data and its location is calculated by interpolating between other known addresses.\n        </p>"}))
    Place.add_member(:time_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeZone, location_name: 'TimeZone', traits: {"smithy.api#documentation" => "<p>The time zone in which the <code>Place</code> is located. Returned only when using\n            HERE or Grab as the selected partner.</p>"}))
    Place.add_member(:unit_type, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'UnitType', traits: {"smithy.api#documentation" => "<p>For addresses with a <code>UnitNumber</code>, the type of unit. For example,\n                <code>Apartment</code>.</p>\n         <note>\n            <p>Returned only for a place index that uses Esri as a data provider.</p>\n         </note>"}))
    Place.add_member(:unit_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'UnitNumber', traits: {"smithy.api#documentation" => "<p>For addresses with multiple units, the unit identifier. Can include numbers and\n            letters, for example <code>3B</code> or <code>Unit 123</code>.</p>\n         <note>\n            <p>Returned only for a place index that uses Esri or Grab as a data provider. Is \n                not returned for <code>SearchPlaceIndexForPosition</code>.</p>\n         </note>"}))
