    SearchForPositionResult.add_member(:distance, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'Distance', traits: {"smithy.api#documentation" => "<p>The distance in meters of a great-circle arc between the query position and the\n            result.</p>\n         <note>\n            <p>A great-circle arc is the shortest path on a sphere, in this case the Earth. This\n                returns the shortest distance between two locations.</p>\n         </note>", "smithy.api#range" => {"min" => 0}, "smithy.api#required" => {}}))
