    SearchForTextResult.add_member(:distance, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'Distance', traits: {"smithy.api#documentation" => "<p>The distance in meters of a great-circle arc between the bias position specified and\n            the result. <code>Distance</code> will be returned only if a bias position was specified\n            in the query.</p>\n         <note>\n            <p>A great-circle arc is the shortest path on a sphere, in this case the Earth. This\n                returns the shortest distance between two locations.</p>\n         </note>", "smithy.api#range" => {"min" => 0}}))
    SearchForTextResult.add_member(:relevance, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Double, location_name: 'Relevance', traits: {"smithy.api#documentation" => "<p>The relative confidence in the match for a result among the results returned. For\n            example, if more fields for an address match (including house number, street, city,\n            country/region, and postal code), the relevance score is closer to 1.</p>\n         <p>Returned only when the partner selected is Esri or Grab.</p>", "smithy.api#range" => {"min" => 0, "max" => 1}}))
