    SearchPlaceIndexForPositionOutput.add_member(:results, Smithy::Schema::Shapes::ShapeRef.new(shape: SearchForPositionResultList, location_name: 'Results', traits: {"smithy.api#documentation" => "<p>Returns a list of Places closest to the specified position. Each result contains\n            additional information about the Places returned.</p>", "smithy.api#required" => {}}))
    SearchPlaceIndexForPositionOutput.type = Types::SearchPlaceIndexForPositionOutput
