    SearchPlaceIndexForPositionSummary.add_member(:data_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'DataSource', traits: {"smithy.api#documentation" => "<p>The geospatial data provider attached to the place index resource specified in the\n            request. Values can be one of the following:</p>\n         <ul>\n            <li>\n               <p>Esri</p>\n            </li>\n            <li>\n               <p>Grab</p>\n            </li>\n            <li>\n               <p>Here</p>\n            </li>\n         </ul>\n         <p>For more information about data providers, see <a href=\"https://docs.aws.amazon.com/location/previous/developerguide/what-is-data-provider.html\">Amazon Location Service data providers</a>.</p>", "smithy.api#required" => {}}))
